import { volcanoCourse } from '../courses/data/volcano';
import type { Course } from '../courses/types';

/** Every playable course, ordered from gentle to chaotic. */
export const COURSES: readonly Course[] = [
  greenHillsCourse,
  pirateBayCourse,
  candyFactoryCourse,
  hauntedMansion,
  neonCity,
  ancientTempleCourse,
  arcticBaseCourse,
  volcanoCourse,
  spaceStation,
  chaosDimension,
];

export const DEFAULT_COURSE_ID = greenHillsCourse.id;

export function courseById(id: string): Course | undefined {
  return COURSES.find((course) => course.id === id);
}

/** Menu ids that do not match a course fall back to the starter course. */
export function resolveCourse(id: string, random: () => number = Math.random): Course {
  if (id === 'random') {
    const index = Math.min(COURSES.length - 1, Math.max(0, Math.floor(random() * COURSES.length)));
    return COURSES[index] ?? greenHillsCourse;
  }
  return courseById(id) ?? greenHillsCourse;
}
